using BotFramework.Discord.Commands;using BotFramework.Discord.Routing;using Games.Basketball.Application.Services;
namespace Games.Basketball.Discord;
public sealed class BasketballDiscordHandler(IBasketballService service):IDiscordMessageHandler{public bool CanHandle(DiscordMessageContext context)=>DiscordCommand.Is(context,"basketball");public async Task HandleAsync(DiscordMessageContext context){var p=DiscordCommand.Parts(context);if(p.Length!=2||!int.TryParse(p[1], System.Globalization.CultureInfo.InvariantCulture, out var amount)||amount<=0){await DiscordCommand.ReplyAsync(context,"Использование: `basketball <ставка>`");return;}var u=DiscordCommand.UserId(context);var s=DiscordCommand.ScopeId(context);var src=DiscordCommand.SourceId(context);var n=DiscordCommand.DisplayName(context);_ = await service.PlaceBetAsync(u,n,s,amount,src,context.CancellationToken);var face=DiscordCommand.RandomFace(1,5);var r=await service.ThrowAsync(u,n,s,face,src,context.CancellationToken);await DiscordCommand.ReplyResultAsync(context,r,"Basketball: "+face);}}
